import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"Coverage, Security, and Static Analysis Gates","description":"","frontmatter":{"work_package_id":"WP02","title":"Coverage, Security, and Static Analysis Gates","lane":"done","dependencies":["WP01"],"base_branch":"021-continuous-integration-and-quality-gates-WP01","base_commit":"5216a91bd2b6d05aa4d8a9df19edd5b2e3d8831e","created_at":"2026-03-01T13:35:19.314038+00:00","subtasks":["T007","T008","T009","T010","T011"],"phase":"Phase 1 - CI Foundation","assignee":"","agent":"claude-haiku","shell_pid":"79606","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/021-continuous-integration-and-quality-gates/tasks/WP02-coverage-security-static-analysis.md","filePath":"specs/021-continuous-integration-and-quality-gates/tasks/WP02-coverage-security-static-analysis.md"}'),l={name:"specs/021-continuous-integration-and-quality-gates/tasks/WP02-coverage-security-static-analysis.md"};function o(r,e,n,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="work-package-prompt-wp02-coverage-security-and-static-analysis-gates" tabindex="-1">Work Package Prompt: WP02 - Coverage, Security, and Static Analysis Gates <a class="header-anchor" href="#work-package-prompt-wp02-coverage-security-and-static-analysis-gates" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Coverage, Security, and Static Analysis Gates&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement Gates 5, 6, and 7: coverage threshold enforcement, security vulnerability scanning, and static analysis.</li><li>Generate structured JSON reports for each gate.</li><li>Enforce 85% coverage per-package and aggregate.</li></ul><p>Success criteria:</p><ul><li>Coverage below 85% in any package fails the gate with current percentage and threshold.</li><li>Known vulnerabilities in dependencies fail the security gate with severity and remediation.</li><li>Anti-patterns and complexity violations fail the static analysis gate.</li><li>All gate reports are structured JSON.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/021-continuous-integration-and-quality-gates/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/021-continuous-integration-and-quality-gates/spec.md</code></li><li>WP01 output: CI pipeline, gate report infrastructure, typecheck/lint/test gates.</li></ul><p>Constraints:</p><ul><li>Coverage enforced per-package AND aggregate at &gt;= 85%.</li><li>Security scan must flag high/critical vulnerabilities as failures.</li><li>Static analysis must detect dead code and complexity violations.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t007-implement-gate-5-coverage-threshold-enforcement" tabindex="-1">Subtask T007 - Implement Gate 5: Coverage threshold enforcement <a class="header-anchor" href="#subtask-t007-implement-gate-5-coverage-threshold-enforcement" aria-label="Permalink to &quot;Subtask T007 - Implement Gate 5: Coverage threshold enforcement&quot;">​</a></h3><ul><li>Purpose: Ensure every workspace package and the aggregate monorepo maintain at least 85% line coverage.</li><li>Steps: <ol><li>Configure Vitest coverage provider (c8 or istanbul) in <code>vitest.config.ts</code> with <code>coverage.enabled: true</code>.</li><li>Set coverage thresholds in Vitest config: <code>lines: 85</code>, <code>functions: 85</code>, <code>branches: 85</code>, <code>statements: 85</code>.</li><li>Configure per-workspace coverage collection so each package is measured independently.</li><li>Add the CI workflow gate step that runs Vitest with coverage enabled and checks thresholds.</li><li>Parse coverage output (JSON summary) to generate a structured gate report listing each package&#39;s coverage percentages against thresholds.</li><li>If any package is below threshold, the report must include: package name, metric (lines/functions/branches/statements), current percentage, threshold.</li><li>Generate an aggregate coverage summary across all packages.</li><li>Add <code>test:coverage</code> script to root <code>package.json</code>.</li><li>Test: remove tests from a package to drop coverage below 85%, verify the gate fails with specific package and percentage.</li><li>Test: verify a zero-coverage package (new package with no tests) fails the gate.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/vitest.config.ts</code> (coverage config)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (test:coverage script)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/.github/workflows/quality-gates.yml</code> (gate step)</li></ul></li><li>Acceptance: <ul><li>Per-package and aggregate coverage enforced at 85%.</li><li>Gate fails with specific package, metric, and percentage on violations.</li><li>Zero-coverage packages are detected.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-implement-gate-6-security-vulnerability-scan" tabindex="-1">Subtask T008 - Implement Gate 6: Security vulnerability scan <a class="header-anchor" href="#subtask-t008-implement-gate-6-security-vulnerability-scan" aria-label="Permalink to &quot;Subtask T008 - Implement Gate 6: Security vulnerability scan&quot;">​</a></h3><ul><li>Purpose: Detect known security vulnerabilities in dependencies and fail the pipeline on high/critical findings.</li><li>Steps: <ol><li>Evaluate available security scanning tools compatible with Bun: <code>bun audit</code> (if available), <code>npm audit</code> as fallback, or a dedicated tool like Snyk CLI.</li><li>Configure the chosen tool to scan all workspace dependencies including transitive dependencies.</li><li>Add the CI workflow gate step that runs the security scan.</li><li>Parse scan output to generate a structured gate report with: vulnerability ID, package name, affected version, severity (low/medium/high/critical), description, and remediation (upgrade path or patch).</li><li>Configure the gate to fail on high or critical severity findings only; medium/low are reported but do not fail.</li><li>Handle prerelease dependencies gracefully: known prerelease advisories from spec 020&#39;s manifest should be cross-referenced.</li><li>Add <code>security:scan</code> script to root <code>package.json</code>.</li><li>Test: add a known-vulnerable dependency version (in a test fixture), verify the gate detects it.</li><li>Handle edge case: scanner not available or network unreachable (fail the gate with a clear message, do not silently pass).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (security:scan script)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/.github/workflows/quality-gates.yml</code> (gate step)</li></ul></li><li>Acceptance: <ul><li>High/critical vulnerabilities fail the gate.</li><li>Reports include vulnerability details and remediation.</li><li>Scanner unavailability fails the gate (not silent pass).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-implement-gate-7-static-analysis" tabindex="-1">Subtask T009 - Implement Gate 7: Static analysis <a class="header-anchor" href="#subtask-t009-implement-gate-7-static-analysis" aria-label="Permalink to &quot;Subtask T009 - Implement Gate 7: Static analysis&quot;">​</a></h3><ul><li>Purpose: Detect anti-patterns, excessive complexity, and dead code that reduce maintainability.</li><li>Steps: <ol><li>Select a static analysis tool compatible with TypeScript and Bun: consider <code>ts-morph</code> for custom analysis, or <code>knip</code> for dead code detection, or a combination.</li><li>Configure complexity thresholds: maximum cyclomatic complexity per function (e.g., 15), maximum function length (e.g., 50 lines), maximum file length (500 lines per constitution).</li><li>Configure dead code detection: unused exports, unreachable code, unused imports.</li><li>Add the CI workflow gate step that runs the static analysis.</li><li>Parse output to generate a structured gate report with: finding type (complexity/dead-code/anti-pattern), file, line, current value, threshold, and description.</li><li>Fail the gate on any threshold violation.</li><li>Add <code>analyze</code> script to root <code>package.json</code>.</li><li>Test: introduce a function with excessive cyclomatic complexity, verify the gate detects it.</li><li>Test: add an unused export, verify dead code detection catches it.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (analyze script)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/.github/workflows/quality-gates.yml</code> (gate step)</li></ul></li><li>Acceptance: <ul><li>Complexity violations detected and reported.</li><li>Dead code detected and reported.</li><li>File length &gt; 500 lines detected.</li><li>Structured gate report produced.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-coverage-manifest-generation" tabindex="-1">Subtask T010 - Coverage manifest generation <a class="header-anchor" href="#subtask-t010-coverage-manifest-generation" aria-label="Permalink to &quot;Subtask T010 - Coverage manifest generation&quot;">​</a></h3><ul><li>Purpose: Produce a per-package and aggregate coverage manifest for downstream consumption (dashboards, PR comments).</li><li>Steps: <ol><li>After the coverage gate runs, generate a <code>coverage-manifest.json</code> artifact.</li><li>Include per-package entries: package name, lines/functions/branches/statements percentages, threshold, pass/fail status.</li><li>Include aggregate entry with the same metrics across all packages.</li><li>Include metadata: commit SHA, timestamp, total test count, total test duration.</li><li>Upload the manifest as a CI artifact alongside gate reports.</li><li>Add a script <code>scripts/coverage-manifest.ts</code> that reads Vitest coverage output and produces the manifest.</li><li>Test: verify the manifest correctly reflects coverage data from known fixtures.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/coverage-manifest.ts</code></li></ul></li><li>Acceptance: <ul><li>Manifest accurately reflects per-package and aggregate coverage.</li><li>Manifest is valid JSON with all required fields.</li></ul></li><li>Parallel: Yes (after T007 coverage gate is functional).</li></ul><h3 id="subtask-t011-gate-integration-tests" tabindex="-1">Subtask T011 - Gate integration tests <a class="header-anchor" href="#subtask-t011-gate-integration-tests" aria-label="Permalink to &quot;Subtask T011 - Gate integration tests&quot;">​</a></h3><ul><li>Purpose: Verify each gate produces correct pass/fail results for known inputs, catching gate regressions.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/gates-integration.test.ts</code>.</li><li>Test coverage gate: provide fixture with below-threshold coverage data, verify gate report shows failure with correct metrics.</li><li>Test coverage gate: provide fixture with above-threshold data, verify gate report shows pass.</li><li>Test security gate: mock scanner output with known vulnerability, verify gate report contains vulnerability details.</li><li>Test security gate: mock clean scanner output, verify pass.</li><li>Test static analysis gate: provide fixture with excessive complexity, verify gate report detects violation.</li><li>Test static analysis gate: provide clean fixture, verify pass.</li><li>Verify all gate reports conform to the shared <code>GateReport</code> schema from WP01.</li><li>Ensure tests are deterministic with mocked external tools.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/gates-integration.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All gate pass/fail scenarios covered.</li><li>Reports validated against schema.</li><li>Tests are deterministic.</li></ul></li><li>Parallel: Yes (after T007-T009 are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Fixture-based tests with known-good and known-bad data for each gate.</li><li>Schema validation for all gate reports.</li><li>Mocked external tools for deterministic results.</li><li>Manual validation on CI by pushing known-bad commits.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Security scanner false positives on prerelease deps.</li><li>Mitigation: Cross-reference with spec 020 manifest; document exceptions without auto-suppressing.</li><li>Risk: Static analysis tool has high false positive rate.</li><li>Mitigation: Start with conservative thresholds; tune based on initial baseline.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm 85% threshold is enforced per-package and aggregate.</li><li>Confirm security gate does not silently pass on scanner failure.</li><li>Confirm static analysis thresholds match constitution requirements.</li><li>Confirm all reports are structured JSON with required fields.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:35:19Z – claude-haiku – shell_pid=79606 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:37:06Z – claude-haiku – shell_pid=79606 – lane=done – Implemented</li></ul>',30)])])}const h=t(l,[["render",o]]);export{g as __pageData,h as default};
